-- A sheet is the unit everything else is kept under. A row is made the first time its id is loaded;
-- a sheet that has never been loaded has no row and starts empty.
CREATE TABLE sheet (
    id         VARCHAR(200) PRIMARY KEY,
    created_by VARCHAR(200) NOT NULL,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
=== resources/db/migration/V2__sheet_today.sql
-- The sheet's own "today": every date decision and default date on the sheet uses it, never the
-- real clock. It starts as the real date the sheet is first loaded.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE) WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
=== resources/db/migration/V3__person.sql
-- People kept on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name       VARCHAR(200) NOT NULL,
    grade      VARCHAR(1)   NOT NULL,
    created_by VARCHAR(200) NOT NULL,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX person_sheet ON person (sheet_id, id);
=== resources/db/migration/V4__person_name_unique.sql
-- A person's name is unique on the sheet, compared without regard to case. Names are stored trimmed.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
=== resources/db/migration/V5__claim.sql
-- A person's claims: an amount (0.00 or more, two decimals), a date and a note (may be empty).
-- Listed newest first (by id).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(19, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(2000)  NOT NULL DEFAULT '',
    created_by VARCHAR(200)   NOT NULL,
    created_at TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
